export const getCloseBillingMonthUrl = (month: string,) => {




  return `/api/v1/billing-months/${month}/close`
}

/**
 * Closes the month: nothing is booked in it any more, and a charge about its days is booked in the earliest open
 * month after it. A closed month is never reopened. Conflicts (409): a month after the current one in
 * Europe/Kyiv (`PERIOD_IN_FUTURE`), a closed month (`PERIOD_CLOSED`), an earlier month that is still open
 * (`PERIOD_CLOSE_ORDER`; months close in order). A month before the first month of the cooperative (or any
 * month while it has none) is 404 `NOT_FOUND`. A listed month without a row is created and closed. The check
 * list does not block closing. Requires `PERIODS_CLOSE`; written to the audit log (`BILLING_MONTH_CLOSED`,
 * entity type `BILLING_MONTH`, label `YYYY-MM`).
 * @summary Close a billing month
 */
